from __future__ import annotations

import json
import os
import threading
import time
from pathlib import Path
from typing import Any

import rclpy
from marvin_msgs.srv import GetRobotFaults, Int, JsonCommand
from rclpy.executors import ExternalShutdownException
from rclpy.node import Node
from rclpy.qos import DurabilityPolicy, HistoryPolicy, QoSProfile, ReliabilityPolicy
from std_msgs.msg import Int16MultiArray, Int32, String
from std_srvs.srv import Trigger

from apex_backend.ros_names import ros_name


DEFAULT_CONTROL_STATE_TOPICS = ("info/robot_state", "info/arm_state")
TELEOP_MOTION_MODE_NAMES = {
    0: "full_body",
    1: "arms_only",
    2: "arms_head",
    3: "arms_body",
}
BASE_MODE_NAMES = {0: "no_base", 1: "joystick", 2: "whole_body"}
JOINT_INPUT_MODE_NAMES = {
    0: "idle",
    1: "teleop",
    2: "planner",
    3: "user",
    4: "replay",
}
IK_INPUT_SOURCE_NAMES = {0: "idle", 1: "vr", 2: "vla", 3: "replay"}
DEFAULT_CONTROL_STATE_STALE_SEC = 2.0
DEFAULT_CONTROL_STATE_WATCHDOG_PERIOD_SEC = 1.0
DEFAULT_CONTROL_STATE_DISCOVERY_GRACE_SEC = 10.0
DEFAULT_CONTROL_STATE_RECOVERY_COOLDOWN_SEC = 10.0
DEFAULT_CONTROL_STATE_RECOVERY_MAX_COOLDOWN_SEC = 60.0
DEFAULT_CONTROL_STATE_STARTUP_GRACE_SEC = 3.0
CONTROL_STATE_BACKEND_RESTART_EXIT_CODE = 75


def _csv_env(name: str, default: tuple[str, ...]) -> tuple[str, ...]:
    raw = os.environ.get(name, "")
    values = tuple(item.strip() for item in raw.split(",") if item.strip())
    return values or default


def _positive_float_env(name: str, default: float, minimum: float = 0.1) -> float:
    raw = os.environ.get(name, "").strip()
    if not raw:
        return default
    try:
        value = float(raw)
    except ValueError:
        return default
    return value if value >= minimum else default


def _boolean_env(name: str, default: bool) -> bool:
    raw = os.environ.get(name, "").strip().lower()
    if not raw:
        return default
    if raw in {"1", "true", "yes", "on"}:
        return True
    if raw in {"0", "false", "no", "off"}:
        return False
    return default


class ApexStateNode(Node):
    READY_MODES = {0, 1, 2, 3}

    def __init__(self) -> None:
        super().__init__("apex_backend_state", namespace=ros_name(""))
        self._lock = threading.Lock()
        self._last_arm_state: list[int] | None = None
        self._last_arm_state_time: float | None = None
        self._last_control_state_monotonic: float | None = None
        self._control_ready = False
        self._set_ready_accepted = False
        self._control_error = False
        self._control_error_message = ""
        self._current_mode = -1
        self._current_speed_factor = 1.0
        self._current_input_mode = -1
        self._current_ik_input_source = -1
        self._current_teleop_motion_mode = -1
        self._current_base_mode = -1
        self._go_home_status: dict[str, Any] = {
            "state": "unknown",
            "active": False,
            "completed": False,
            "success": False,
            "motion_id": 0,
            "progress": 0.0,
            "elapsed_sec": 0.0,
            "planned_duration_sec": 0.0,
            "max_joint_error_rad": None,
            "feedback_fresh": False,
            "message": "No go-home status has been received.",
            "received": False,
        }
        self._last_go_home_status_time: float | None = None
        self._playback_status: dict[str, Any] = {
            "is_playing": False,
            "is_paused": False,
            "playback_rate": 1.0,
            "current_time": 0.0,
            "duration": 0.0,
            "progress": 0.0,
            "bag_path": None,
        }
        self._bag_info_cache: dict[str, Any] = {}
        username = (
            os.environ.get("SUDO_USER")
            or os.environ.get("USER")
            or os.environ.get("LOGNAME")
            or "marvin"
        )
        storage_root = os.environ.get(
            "BAG_STORAGE_ROOT", os.path.join("/media", username, "BAG_STORAGE")
        )
        self._bag_directory = os.path.join(storage_root, "recorded_bags")
        self._latest_robot_info: dict[str, Any] = {
            "robot_type": "unknown",
            "controller_version": None,
            "controller_version_text": "unknown",
            "base_model": None,
            "arm_model": None,
            "stand_shoulder_width_m": None,
            "stand_height_m": None,
            "stand_options": ["legacy", "new", "m6stand", "m6litestand", "user"],
            "stamp_ns": None,
            "age_sec": None,
            "received": False,
        }
        self._last_robot_info_time: float | None = None
        self._control_state_topics = tuple(
            dict.fromkeys(
                ros_name(topic)
                for topic in _csv_env("APEX_CONTROL_STATE_TOPICS", DEFAULT_CONTROL_STATE_TOPICS)
            )
        )
        self._control_state_subscriptions: dict[str, Any] = {}
        self._control_state_recovery_count = 0
        self._control_state_consecutive_recovery_count = 0
        self._control_state_last_recovery_reason = ""
        self._control_state_watchdog_started_monotonic = time.monotonic()
        self._control_state_last_recovery_monotonic = float("-inf")
        self._control_state_last_publisher_count = 0
        self._control_state_publisher_present_since: float | None = None
        self._control_state_next_recovery_monotonic = float("-inf")
        self._control_state_stale_sec = _positive_float_env(
            "APEX_CONTROL_STATE_STALE_SEC", DEFAULT_CONTROL_STATE_STALE_SEC
        )
        self._control_state_watchdog_period_sec = _positive_float_env(
            "APEX_CONTROL_STATE_WATCHDOG_PERIOD_SEC",
            DEFAULT_CONTROL_STATE_WATCHDOG_PERIOD_SEC,
        )
        self._control_state_recovery_cooldown_sec = _positive_float_env(
            "APEX_CONTROL_STATE_RECOVERY_COOLDOWN_SEC",
            DEFAULT_CONTROL_STATE_RECOVERY_COOLDOWN_SEC,
        )
        self._control_state_discovery_grace_sec = _positive_float_env(
            "APEX_CONTROL_STATE_DISCOVERY_GRACE_SEC",
            DEFAULT_CONTROL_STATE_DISCOVERY_GRACE_SEC,
        )
        self._control_state_recovery_max_cooldown_sec = max(
            self._control_state_recovery_cooldown_sec,
            _positive_float_env(
                "APEX_CONTROL_STATE_RECOVERY_MAX_COOLDOWN_SEC",
                DEFAULT_CONTROL_STATE_RECOVERY_MAX_COOLDOWN_SEC,
            ),
        )
        self._control_state_recovery_backoff_sec = (
            self._control_state_recovery_cooldown_sec
        )
        self._control_state_backend_restart_enabled = _boolean_env(
            "APEX_CONTROL_STATE_BACKEND_RESTART_ENABLED", True
        )
        self._control_state_startup_grace_sec = _positive_float_env(
            "APEX_CONTROL_STATE_STARTUP_GRACE_SEC",
            DEFAULT_CONTROL_STATE_STARTUP_GRACE_SEC,
        )
        self._control_state_qos = QoSProfile(
            reliability=ReliabilityPolicy.BEST_EFFORT,
            durability=DurabilityPolicy.VOLATILE,
            history=HistoryPolicy.KEEP_LAST,
            depth=1,
        )

        self.mode_service_name = ros_name("control/set_mode")
        self.clear_fault_service_name = ros_name("control/clear_fault")
        self.get_faults_service_name = ros_name("control/get_faults")
        self.ready_service_name = ros_name("control/set_ready")
        self.speed_service_name = ros_name("control/set_vel_ratio")
        self.go_home_service_name = ros_name("control/go_home")
        self.set_input_service_name = ros_name("control/set_input")
        self.set_ik_input_service_name = ros_name("control/set_ik_input")
        self.set_teleop_motion_mode_service_name = ros_name("control/set_teleop_motion_mode")
        self.reset_grippers_service_name = ros_name("control/reset_grippers")
        # lingho_base_control intentionally runs at the root namespace: its
        # vendor base topics are global while its VR inputs point into /tj.
        self.set_base_mode_service_name = "/control/base_teleop/set_mode"
        self.mode_client = self.create_client(Int, self.mode_service_name)
        self.clear_fault_client = self.create_client(
            Trigger, self.clear_fault_service_name
        )
        self.get_faults_client = self.create_client(
            GetRobotFaults, self.get_faults_service_name
        )
        self.ready_client = self.create_client(Trigger, self.ready_service_name)
        self.speed_client = self.create_client(Int, self.speed_service_name)
        self.home_arm_client = self.create_client(Trigger, self.go_home_service_name)
        self.go_home_client = self.create_client(Trigger, self.go_home_service_name)
        # apex-tool is launched in the configured Apex namespace, so resolve
        # its reset service exactly like the other robot/tool interfaces.
        self.reset_grippers_client = self.create_client(
            Trigger, self.reset_grippers_service_name
        )
        self.set_input_client = self.create_client(Int, self.set_input_service_name)
        self.set_ik_input_client = self.create_client(Int, self.set_ik_input_service_name)
        self.set_teleop_motion_mode_client = self.create_client(
            Int, self.set_teleop_motion_mode_service_name
        )
        self.set_base_mode_client = self.create_client(Int, self.set_base_mode_service_name)
        self.playback_control_client = self.create_client(JsonCommand, ros_name("playback/control"))
        self.recorder_control_client = self.create_client(JsonCommand, ros_name("recorder/control"))
        # Fast DDS can leave a long-lived client matched to a service server
        # that disappeared when Robot or Teleop restarted. wait_for_service()
        # may still report true, but requests sent through that stale client
        # never receive a response. Keep enough metadata to replace only the
        # idempotent setter clients after a failed call, and serialize recovery
        # so concurrent API requests cannot destroy each other's client.
        self._recoverable_service_clients: dict[str, tuple[Any, str]] = {
            "mode_client": (Int, self.mode_service_name),
            "clear_fault_client": (Trigger, self.clear_fault_service_name),
            "get_faults_client": (GetRobotFaults, self.get_faults_service_name),
            "speed_client": (Int, self.speed_service_name),
            "set_input_client": (Int, self.set_input_service_name),
            "set_ik_input_client": (Int, self.set_ik_input_service_name),
            "set_teleop_motion_mode_client": (
                Int,
                self.set_teleop_motion_mode_service_name,
            ),
            "set_base_mode_client": (Int, self.set_base_mode_service_name),
        }
        self._service_client_locks = {
            attribute: threading.Lock()
            for attribute in self._recoverable_service_clients
        }

        self._create_control_state_subscriptions()
        self._control_state_watchdog_timer = self.create_timer(
            self._control_state_watchdog_period_sec,
            self._control_state_watchdog,
        )
        latched_qos = QoSProfile(
            reliability=ReliabilityPolicy.RELIABLE,
            durability=DurabilityPolicy.TRANSIENT_LOCAL,
            history=HistoryPolicy.KEEP_LAST,
            depth=1,
        )
        self.create_subscription(Int32, ros_name("control/input_mode"), self._input_mode_callback, latched_qos)
        self.create_subscription(
            Int32,
            ros_name("info/ik_request_mux/active_source"),
            self._ik_input_source_callback,
            latched_qos,
        )
        self.create_subscription(
            Int32,
            ros_name("info/teleop_motion_mode"),
            self._teleop_motion_mode_callback,
            latched_qos,
        )
        self.create_subscription(
            Int32,
            "/info/base_teleop/active_mode",
            self._base_mode_callback,
            latched_qos,
        )
        self.create_subscription(
            String,
            ros_name("info/go_home_status"),
            self._go_home_status_callback,
            latched_qos,
        )
        self.create_subscription(String, ros_name("playback_status"), self._playback_status_callback, 10)
        self._create_robot_info_subscription()
        self.get_logger().info("Apex backend state node started")

    def _robot_state_callback(self, msg: Int16MultiArray) -> None:
        self._control_state_callback(ros_name("info/robot_state"), msg)

    def _arm_state_callback(self, msg: Int16MultiArray) -> None:
        self._control_state_callback(ros_name("info/arm_state"), msg)

    def _create_control_state_subscriptions(self) -> None:
        for topic in self._control_state_topics:
            if topic in self._control_state_subscriptions:
                continue
            try:
                self._control_state_subscriptions[topic] = self.create_subscription(
                    Int16MultiArray,
                    topic,
                    lambda msg, source_topic=topic: self._control_state_callback(
                        source_topic, msg
                    ),
                    self._control_state_qos,
                )
            except Exception as exc:
                self.get_logger().error(
                    f"Failed to create robot control state subscription for {topic}: {exc}"
                )

    def _control_state_publisher_count(self) -> int:
        count = 0
        for topic in self._control_state_topics:
            try:
                count += len(self.get_publishers_info_by_topic(topic))
            except Exception:
                subscription = self._control_state_subscriptions.get(topic)
                get_count = getattr(subscription, "get_publisher_count", None)
                if get_count is not None:
                    try:
                        count += int(get_count())
                    except Exception:
                        pass
        return count

    def _mark_control_state_stale(self, age_sec: float | None) -> None:
        age_text = "never received" if age_sec is None else f"stale for {age_sec:.1f}s"
        with self._lock:
            self._control_ready = False
            self._set_ready_accepted = False
            self._control_error = True
            self._control_error_message = f"Robot control state is {age_text}"
            self._current_mode = -1

    def _rebuild_control_state_subscriptions(self, reason: str, now_monotonic: float) -> None:
        old_subscriptions = list(self._control_state_subscriptions.values())
        self._control_state_subscriptions.clear()
        for subscription in old_subscriptions:
            try:
                self.destroy_subscription(subscription)
            except Exception as exc:
                self.get_logger().warning(
                    f"Failed to destroy stale robot state subscription: {exc}"
                )

        self._create_control_state_subscriptions()
        with self._lock:
            self._control_state_last_recovery_monotonic = now_monotonic
            self._control_state_recovery_count += 1
            self._control_state_consecutive_recovery_count += 1
            self._control_state_last_recovery_reason = reason
            cooldown_sec = self._control_state_recovery_backoff_sec
            self._control_state_next_recovery_monotonic = (
                now_monotonic + cooldown_sec
            )
            self._control_state_recovery_backoff_sec = min(
                self._control_state_recovery_max_cooldown_sec,
                max(
                    self._control_state_recovery_cooldown_sec,
                    cooldown_sec * 2.0,
                ),
            )
        self.get_logger().warning(
            "Robot control state watchdog rebuilt "
            f"{len(self._control_state_subscriptions)} subscription(s): {reason}; "
            f"next retry in {cooldown_sec:.1f}s"
        )

    def _restart_backend_for_control_state(self, reason: str) -> None:
        self.get_logger().error(
            "Robot control state is still unavailable after subscription recovery; "
            "restarting the Backend process to recreate its DDS participant: "
            f"{reason}"
        )
        # The production service uses Restart=on-failure. Exiting with a
        # dedicated non-zero code recreates the rclpy context and DDS
        # participant without stopping or commanding the Robot service.
        os._exit(CONTROL_STATE_BACKEND_RESTART_EXIT_CODE)

    def _control_state_watchdog(self) -> None:
        now_monotonic = time.monotonic()
        if (
            now_monotonic - self._control_state_watchdog_started_monotonic
            < self._control_state_startup_grace_sec
        ):
            return

        with self._lock:
            last_message = self._last_control_state_monotonic
        age_sec = None if last_message is None else max(0.0, now_monotonic - last_message)
        if age_sec is not None and age_sec <= self._control_state_stale_sec:
            return

        self._mark_control_state_stale(age_sec)
        publisher_count = self._control_state_publisher_count()
        previous_publisher_count = self._control_state_last_publisher_count
        self._control_state_last_publisher_count = publisher_count
        if publisher_count <= 0:
            self._control_state_publisher_present_since = None
            self._control_state_next_recovery_monotonic = float("-inf")
            self._control_state_recovery_backoff_sec = (
                self._control_state_recovery_cooldown_sec
            )
            self._control_state_consecutive_recovery_count = 0
            return

        if previous_publisher_count <= 0:
            # A Robot process can appear in the DDS graph before a newly
            # matched subscription is ready to receive data. Keep the current
            # handles alive for a full discovery window instead of destroying
            # them every watchdog cycle.
            self._control_state_publisher_present_since = now_monotonic
            self._control_state_next_recovery_monotonic = (
                now_monotonic + self._control_state_discovery_grace_sec
            )
            self._control_state_recovery_backoff_sec = (
                self._control_state_recovery_cooldown_sec
            )
            self.get_logger().info(
                "Robot control state publisher discovered; waiting "
                f"{self._control_state_discovery_grace_sec:.1f}s for DDS matching"
            )
            return

        if now_monotonic < self._control_state_next_recovery_monotonic:
            return

        reason = (
            "publisher discovered but no state has been received"
            if age_sec is None
            else f"publisher present but state is stale for {age_sec:.1f}s"
        )
        if (
            self._control_state_backend_restart_enabled
            and self._control_state_consecutive_recovery_count >= 1
        ):
            self._restart_backend_for_control_state(reason)
            return
        self._rebuild_control_state_subscriptions(reason, now_monotonic)

    def _input_mode_callback(self, msg: Int32) -> None:
        with self._lock:
            self._current_input_mode = int(msg.data)

    def _ik_input_source_callback(self, msg: Int32) -> None:
        with self._lock:
            self._current_ik_input_source = int(msg.data)

    def _teleop_motion_mode_callback(self, msg: Int32) -> None:
        with self._lock:
            self._current_teleop_motion_mode = int(msg.data)

    def _base_mode_callback(self, msg: Int32) -> None:
        mode = int(msg.data)
        if mode not in BASE_MODE_NAMES:
            self.get_logger().warning(f"Ignoring invalid base teleop mode: {mode}")
            return
        with self._lock:
            self._current_base_mode = mode

    def _go_home_status_callback(self, msg: String) -> None:
        try:
            status = json.loads(msg.data)
            if not isinstance(status, dict) or not isinstance(status.get("state"), str):
                raise ValueError("go-home status must be a JSON object with a state string")
            status["received"] = True
            with self._lock:
                self._go_home_status = status
                self._last_go_home_status_time = time.time()
        except (json.JSONDecodeError, TypeError, ValueError) as exc:
            self.get_logger().warning(f"Ignoring invalid go-home status: {exc}")

    def _playback_status_callback(self, msg: String) -> None:
        try:
            status = json.loads(msg.data)
            with self._lock:
                self._playback_status = status
        except Exception:
            pass

    def _control_state_callback(self, source_topic: str, msg: Int16MultiArray) -> None:
        now = time.time()
        now_monotonic = time.monotonic()
        data = list(msg.data)
        ready = False
        error = False
        error_message = ""
        mode = -1

        if len(data) < 2:
            error = True
            error_message = f"{source_topic} payload too short: {len(data)}"
        else:
            mode_a, mode_b = data[:2]
            if mode_a == -1 and mode_b == -1:
                ready = False
                mode = -1
            elif mode_a == mode_b and mode_a in self.READY_MODES:
                ready = True
                mode = mode_a
            elif mode_a != mode_b:
                error = True
                error_message = f"Control state mismatch: left={mode_a}, right={mode_b}"
            else:
                error = True
                error_message = f"Invalid control state: left={mode_a}, right={mode_b}"

        with self._lock:
            self._last_arm_state = data
            self._last_arm_state_time = now
            self._last_control_state_monotonic = now_monotonic
            self._control_state_recovery_backoff_sec = (
                self._control_state_recovery_cooldown_sec
            )
            self._control_state_consecutive_recovery_count = 0
            self._control_state_next_recovery_monotonic = float("-inf")
            self._control_ready = ready
            self._set_ready_accepted = ready
            self._control_error = error
            self._control_error_message = error_message
            self._current_mode = mode

    def _create_robot_info_subscription(self) -> None:
        try:
            from marvin_msgs.msg import RobotInfo
        except (ImportError, ModuleNotFoundError):
            self.get_logger().warning("marvin_msgs/msg/RobotInfo is unavailable")
            return
        self.create_subscription(RobotInfo, ros_name("info/robot_info"), self._robot_info_callback, 10)

    def _robot_info_callback(self, msg: Any) -> None:
        stamp = getattr(getattr(msg, "header", None), "stamp", None)
        stamp_ns = None
        if stamp is not None:
            stamp_ns = int(getattr(stamp, "sec", 0)) * 1_000_000_000 + int(getattr(stamp, "nanosec", 0))

        now = time.time()
        with self._lock:
            self._last_robot_info_time = now
            base_model = getattr(msg, "base_model", None)
            self._latest_robot_info = {
                "robot_type": getattr(msg, "robot_type", "unknown"),
                "controller_version": _to_int(getattr(msg, "controller_version", None)),
                "controller_version_text": getattr(msg, "controller_version_text", "unknown"),
                "base_model": base_model,
                "arm_model": getattr(msg, "arm_model", None),
                "stand_shoulder_width_m": getattr(msg, "stand_shoulder_width_m", None),
                "stand_height_m": getattr(msg, "stand_height_m", None),
                "stand_options": ["legacy", "new", "m6stand", "m6litestand", "user"],
                "stamp_ns": stamp_ns,
                "age_sec": 0.0,
                "received": True,
            }

    def snapshot(self) -> dict[str, Any]:
        with self._lock:
            last_time = self._last_arm_state_time
            age = None if last_time is None else max(0.0, time.time() - last_time)
            stale_sec = getattr(
                self, "_control_state_stale_sec", DEFAULT_CONTROL_STATE_STALE_SEC
            )
            state_healthy = age is not None and age <= stale_sec
            input_mode = getattr(self, "_current_input_mode", -1)
            ik_input_source = getattr(self, "_current_ik_input_source", -1)
            teleop_motion_mode = getattr(self, "_current_teleop_motion_mode", -1)
            base_mode = getattr(self, "_current_base_mode", -1)
            go_home_status = dict(self._go_home_status)
            go_home_last_time = self._last_go_home_status_time
            go_home_status["age_sec"] = (
                None if go_home_last_time is None else max(0.0, time.time() - go_home_last_time)
            )
            return {
                "control_ready": self._control_ready,
                "control_error": self._control_error,
                "control_error_message": self._control_error_message,
                "arm_state": self._last_arm_state,
                "arm_state_age_sec": age,
                "control_state_healthy": state_healthy,
                "control_state_recovery_count": getattr(
                    self, "_control_state_recovery_count", 0
                ),
                "control_state_last_recovery_reason": getattr(
                    self, "_control_state_last_recovery_reason", ""
                ),
                "current_mode": self._current_mode,
                "speed_factor": self._current_speed_factor,
                "current_input_mode": input_mode,
                "current_input_mode_name": JOINT_INPUT_MODE_NAMES.get(input_mode, "unknown"),
                "current_ik_input_source": ik_input_source,
                "current_ik_input_source_name": IK_INPUT_SOURCE_NAMES.get(
                    ik_input_source, "unknown"
                ),
                "teleop_motion_mode": teleop_motion_mode,
                "teleop_motion_mode_name": TELEOP_MOTION_MODE_NAMES.get(
                    teleop_motion_mode, "unknown"
                ),
                "base_mode": base_mode,
                "base_mode_name": BASE_MODE_NAMES.get(base_mode, "unknown"),
                "go_home_status": go_home_status,
                # Pro exposes this same planner operation as robot/reset,
                # while Gento exposes it as robot/go_home.
                "reset_status": dict(go_home_status),
            }

    def robot_info_snapshot(self) -> dict[str, Any]:
        with self._lock:
            robot_info = dict(self._latest_robot_info)
            last_time = self._last_robot_info_time
        robot_info["age_sec"] = None if last_time is None else max(0.0, time.time() - last_time)
        return robot_info

    def require_robot_service_active(self, robot_status: dict[str, Any]) -> tuple[bool, str]:
        if robot_status.get("active_state") != "active":
            return False, "Robot Control service is not active"
        if robot_status.get("error"):
            return False, "Robot Control service reports a runtime error"
        return True, ""

    def set_mode(self, mode: int) -> dict[str, Any]:
        request = Int.Request()
        request.data = mode
        # MarvinSDK applies the two arm modes sequentially. On real hardware
        # impedance mode can take several seconds even though it completes
        # successfully, so this must exceed the robot node's 6.5 s bounded
        # confirmation window.
        response = self._call(
            self.mode_client,
            request,
            self.mode_service_name,
            timeout_sec=8.0,
            recoverable_client="mode_client",
        )
        if _int_response_success(response):
            with self._lock:
                self._current_mode = mode
            return {"success": True, "mode": mode, "error_code": _response_error_code(response)}
        result = _int_response_error(response)
        # The Int service carries one legacy error_code field. Query the SDK
        # fault snapshot as well so the caller can identify the failing module
        # and individual servo without changing the existing set_mode API.
        try:
            fault_result = self.get_faults(timeout_sec=1.0)
            result["faults"] = fault_result.get("faults", [])
            result["fault_query_success"] = fault_result.get("success", False)
            if fault_result.get("message"):
                result["fault_message"] = fault_result["message"]
        except (RuntimeError, TimeoutError) as exc:
            result["fault_query_success"] = False
            result["fault_query_error"] = str(exc)
        return result

    def clear_fault(self) -> dict[str, Any]:
        response = self._call(
            self.clear_fault_client,
            Trigger.Request(),
            self.clear_fault_service_name,
            recoverable_client="clear_fault_client",
        )
        success = bool(getattr(response, "success", False))
        message = str(getattr(response, "message", "") or "")
        result: dict[str, Any] = {"success": success, "message": message}
        if not success:
            result["error"] = message or "Failed to clear robot faults"
        return result

    def get_faults(self, timeout_sec: float = 2.0) -> dict[str, Any]:
        response = self._call(
            self.get_faults_client,
            GetRobotFaults.Request(),
            self.get_faults_service_name,
            timeout_sec=timeout_sec,
            recoverable_client="get_faults_client",
        )
        faults = []
        for fault in getattr(response, "faults", []) or []:
            state_error_code = int(getattr(fault, "state_error_code", 0))
            servo_error_codes = [
                int(code) for code in (getattr(fault, "servo_error_codes", []) or [])
            ]
            faults.append(
                {
                    "component": str(getattr(fault, "component", "")),
                    "current_state": int(getattr(fault, "current_state", 0)),
                    "commanded_state": int(getattr(fault, "commanded_state", 0)),
                    "state_error_code": state_error_code,
                    "state_error_code_hex": f"0x{state_error_code:08X}",
                    "servo_error_codes": servo_error_codes,
                    "servo_error_codes_hex": [
                        f"0x{code:08X}" for code in servo_error_codes
                    ],
                    "has_fault": bool(getattr(fault, "has_fault", False)),
                }
            )
        return {
            "success": bool(getattr(response, "success", False)),
            "error_code": _response_error_code(response),
            "message": str(getattr(response, "message", "") or ""),
            "faults": faults,
        }

    def set_input(self, input_id: int) -> dict[str, Any]:
        request = Int.Request()
        request.data = input_id
        response = self._call(
            self.set_input_client,
            request,
            self.set_input_service_name,
            recoverable_client="set_input_client",
        )
        if _int_response_success(response):
            with self._lock:
                self._current_input_mode = input_id
            return {
                "success": True,
                "input": input_id,
                "error_code": _response_error_code(response),
            }
        return _int_response_error(response)

    def set_ik_input(self, input_id: int) -> dict[str, Any]:
        if input_id not in IK_INPUT_SOURCE_NAMES:
            return {
                "success": False,
                "error": "input must be 0=idle, 1=vr, 2=vla, or 3=replay",
            }
        request = Int.Request()
        request.data = input_id
        response = self._call(
            self.set_ik_input_client,
            request,
            self.set_ik_input_service_name,
            recoverable_client="set_ik_input_client",
        )
        if _int_response_success(response):
            with self._lock:
                self._current_ik_input_source = input_id
            return {
                "success": True,
                "input": input_id,
                "source": IK_INPUT_SOURCE_NAMES[input_id],
                "error_code": _response_error_code(response),
            }
        return _int_response_error(response)

    def set_teleop_motion_mode(self, mode: int) -> dict[str, Any]:
        if mode not in TELEOP_MOTION_MODE_NAMES:
            supported = ", ".join(
                f"{value}={name}"
                for value, name in sorted(TELEOP_MOTION_MODE_NAMES.items())
            )
            return {
                "success": False,
                "error": f"mode must be {supported}",
            }
        request = Int.Request()
        request.data = mode
        response = self._call(
            self.set_teleop_motion_mode_client,
            request,
            self.set_teleop_motion_mode_service_name,
            recoverable_client="set_teleop_motion_mode_client",
        )
        if bool(getattr(response, "success", False)):
            with self._lock:
                self._current_teleop_motion_mode = mode
            return {
                "success": True,
                "mode": TELEOP_MOTION_MODE_NAMES[mode],
                "value": mode,
                "error_code": _response_error_code(response),
            }
        return _int_response_error(response)

    def set_base_mode(self, mode: int) -> dict[str, Any]:
        if mode not in BASE_MODE_NAMES:
            return {
                "success": False,
                "error": "mode must be 0=no_base, 1=joystick, or 2=whole_body",
            }
        request = Int.Request()
        request.data = mode
        response = self._call(
            self.set_base_mode_client,
            request,
            self.set_base_mode_service_name,
            recoverable_client="set_base_mode_client",
        )
        if bool(getattr(response, "success", False)):
            with self._lock:
                self._current_base_mode = mode
            return {
                "success": True,
                "mode": mode,
                "mode_name": BASE_MODE_NAMES[mode],
            }
        return _int_response_error(response)

    def set_ready(self) -> dict[str, Any]:
        response = self._call(self.ready_client, Trigger.Request(), self.ready_service_name)
        if response.success:
            with self._lock:
                self._set_ready_accepted = True
                self._control_ready = True
        return {"success": bool(response.success), "message": response.message}

    def set_vel_ratio(self, speed_factor: float) -> dict[str, Any]:
        if speed_factor < 0:
            return {"success": False, "error": "speed_factor must be greater than or equal to 0"}
        request = Int.Request()
        request.data = int(speed_factor)
        response = self._call(
            self.speed_client,
            request,
            self.speed_service_name,
            recoverable_client="speed_client",
        )
        if _int_response_success(response):
            with self._lock:
                self._current_speed_factor = speed_factor
            return {"success": True, "speed_factor": speed_factor, "error_code": _response_error_code(response)}
        return _int_response_error(response)

    def home_arm(self) -> dict[str, Any]:
        response = self._call(self.home_arm_client, Trigger.Request(), self.go_home_service_name)
        return {"success": bool(response.success), "message": response.message}

    def go_home(self) -> dict[str, Any]:
        response = self._call(self.go_home_client, Trigger.Request(), self.go_home_service_name)
        return {"success": bool(response.success), "message": response.message}

    def get_go_home_status(self) -> dict[str, Any]:
        with self._lock:
            status = dict(self._go_home_status)
            last_time = self._last_go_home_status_time
        status["age_sec"] = None if last_time is None else max(0.0, time.time() - last_time)
        return status

    def get_reset_status(self) -> dict[str, Any]:
        return self.get_go_home_status()

    def reset_grippers(self) -> dict[str, Any]:
        response = self._call(
            self.reset_grippers_client,
            Trigger.Request(),
            self.reset_grippers_service_name,
        )
        return {"success": bool(response.success), "message": response.message}

    # ── Playback ──────────────────────────────────────────────────────────────

    def get_playback_status(self) -> dict[str, Any]:
        with self._lock:
            return dict(self._playback_status)

    def playback_control(self, command: dict[str, Any]) -> dict[str, Any]:
        return self._json_command_call(
            self.playback_control_client,
            "playback/control",
            command,
            timeout_sec=10.0,
        )

    # ── Recording ─────────────────────────────────────────────────────────────

    def recorder_control(self, command: dict[str, Any]) -> dict[str, Any]:
        return self._json_command_call(
            self.recorder_control_client,
            "recorder/control",
            command,
            timeout_sec=10.0,
        )

    def get_bag_files(self) -> list[dict[str, Any]]:
        bag_files: list[dict[str, Any]] = []
        try:
            bag_dir = Path(self._bag_directory)
            if not bag_dir.exists():
                return bag_files
            for metadata_path in bag_dir.rglob("metadata.yaml"):
                rosbag_dir = metadata_path.parent
                if not rosbag_dir.is_dir():
                    continue
                try:
                    display_dir = rosbag_dir.parent if rosbag_dir.name == "data" else rosbag_dir
                    stat_info = display_dir.stat()
                    bag_data_files = list(rosbag_dir.glob("*.mcap")) or list(rosbag_dir.glob("*.db3"))
                    video_dir = display_dir / "video"
                    video_files = list(video_dir.glob("*")) if video_dir.is_dir() else []
                    total_size = sum(
                        f.stat().st_size for f in [*bag_data_files, *video_files] if f.is_file()
                    )
                    rosbag_path = str(rosbag_dir)
                    display_path = str(display_dir)
                    bag_files.append({
                        "path": rosbag_path,
                        "name": display_dir.name,
                        "size": total_size,
                        "modified_time": stat_info.st_mtime,
                        "created_time": stat_info.st_ctime,
                        "root_path": display_path,
                    })
                except Exception as exc:
                    self.get_logger().warning(f"Failed to read bag info {rosbag_dir}: {exc}")
            bag_files.sort(key=lambda x: x.get("modified_time", 0), reverse=True)
        except Exception as exc:
            self.get_logger().error(f"Failed to scan bag directory: {exc}")
        return bag_files

    def get_bag_info(self, bag_path: str, fast_mode: bool = True) -> dict[str, Any] | None:
        try:
            import yaml
            from rosbag2_py import ConverterOptions, SequentialReader, StorageOptions

            if not os.path.exists(bag_path):
                return None

            cache_key = f"{bag_path}:{fast_mode}"
            try:
                current_mtime = Path(bag_path).stat().st_mtime
            except OSError:
                return None
            if cache_key in self._bag_info_cache:
                cached_info, cached_mtime = self._bag_info_cache[cache_key]
                if cached_mtime == current_mtime:
                    return cached_info

            metadata_path = Path(bag_path) / "metadata.yaml"
            if metadata_path.exists():
                try:
                    with open(metadata_path) as f:
                        metadata = yaml.safe_load(f)
                    bag_info = metadata.get("rosbag2_bagfile_information", {})
                    topics_info = bag_info.get("topics_with_message_count", [])
                    result = {
                        "topics": [t["topic_metadata"]["name"] for t in topics_info],
                        "topic_count": len(topics_info),
                        "message_count": sum(t["message_count"] for t in topics_info),
                        "duration": bag_info.get("duration", {}).get("nanoseconds", 0) / 1e9,
                        "start_time": bag_info.get("starting_time", {}).get("nanoseconds_since_epoch", 0) / 1e9,
                    }
                    result["end_time"] = result["start_time"] + result["duration"]
                    self._bag_info_cache[cache_key] = (result, current_mtime)
                    return result
                except Exception:
                    pass

            reader = SequentialReader()
            reader.open(
                StorageOptions(uri=bag_path, storage_id="mcap"),
                ConverterOptions(input_serialization_format="cdr", output_serialization_format="cdr"),
            )
            topics: set[str] = set()
            message_count = 0
            start_time = end_time = None
            while reader.has_next():
                topic, _data, ts = reader.read_next()
                topics.add(topic)
                message_count += 1
                if start_time is None or ts < start_time:
                    start_time = ts
                if end_time is None or ts > end_time:
                    end_time = ts
            duration = (end_time - start_time) / 1e9 if start_time and end_time else 0.0
            result = {
                "topics": sorted(topics),
                "topic_count": len(topics),
                "message_count": message_count,
                "duration": duration,
                "start_time": start_time / 1e9 if start_time else 0,
                "end_time": end_time / 1e9 if end_time else 0,
            }
            self._bag_info_cache[cache_key] = (result, current_mtime)
            return result
        except Exception as exc:
            self.get_logger().error(f"get_bag_info failed for {bag_path}: {exc}")
            return None

    def _json_command_call(
        self,
        client: Any,
        service_name: str,
        command: dict[str, Any],
        timeout_sec: float = 5.0,
    ) -> dict[str, Any]:
        request = JsonCommand.Request()
        request.command_json = json.dumps(command, ensure_ascii=False)
        response = self._call(client, request, service_name, timeout_sec=timeout_sec)
        if response.result_json:
            try:
                result = json.loads(response.result_json)
            except json.JSONDecodeError:
                result = {"status": "error", "error_message": response.result_json}
        else:
            result = {}
        if not response.success and result.get("status") != "error":
            result["status"] = "error"
            result["error_message"] = response.message
        return result

    def _call_once(
        self,
        client: Any,
        request: Any,
        service_name: str,
        timeout_sec: float,
        discovery_timeout_sec: float = 1.0,
    ) -> Any:
        if not client.wait_for_service(timeout_sec=discovery_timeout_sec):
            raise RuntimeError(f"Service unavailable: {service_name}")
        future = client.call_async(request)
        deadline = time.monotonic() + timeout_sec
        while time.monotonic() < deadline:
            if future.done():
                return future.result()
            time.sleep(0.02)
        raise TimeoutError(f"Service call timed out: {service_name}")

    def _rebuild_service_client(
        self,
        client_attribute: str,
        stale_client: Any,
        service_name: str,
    ) -> Any:
        try:
            service_type, configured_service_name = self._recoverable_service_clients[
                client_attribute
            ]
        except KeyError as exc:
            raise RuntimeError(
                f"Service client is not registered for recovery: {client_attribute}"
            ) from exc
        if configured_service_name != service_name:
            raise RuntimeError(
                "Service recovery configuration mismatch: "
                f"{client_attribute} resolves to {configured_service_name}, not {service_name}"
            )

        current_client = getattr(self, client_attribute)
        if current_client is not stale_client:
            return current_client
        try:
            self.destroy_client(stale_client)
        except Exception as exc:
            self.get_logger().warning(
                f"Failed to destroy stale service client {service_name}: {exc}"
            )
        replacement = self.create_client(service_type, service_name)
        setattr(self, client_attribute, replacement)
        return replacement

    def _call(
        self,
        client: Any,
        request: Any,
        service_name: str,
        timeout_sec: float = 2.0,
        recoverable_client: str | None = None,
    ) -> Any:
        if recoverable_client is None:
            return self._call_once(client, request, service_name, timeout_sec)

        try:
            recovery_lock = self._service_client_locks[recoverable_client]
        except KeyError as exc:
            raise RuntimeError(
                f"Service client is not registered for recovery: {recoverable_client}"
            ) from exc

        with recovery_lock:
            # The caller may have captured the old handle before another API
            # request rebuilt it while waiting for this lock.
            active_client = getattr(self, recoverable_client)
            try:
                return self._call_once(
                    active_client,
                    request,
                    service_name,
                    timeout_sec,
                )
            except (RuntimeError, TimeoutError) as first_error:
                self.get_logger().warning(
                    f"Service call failed; rebuilding client and retrying once: "
                    f"{service_name}: {first_error}"
                )
                replacement = self._rebuild_service_client(
                    recoverable_client,
                    active_client,
                    service_name,
                )
                return self._call_once(
                    replacement,
                    request,
                    service_name,
                    timeout_sec,
                    discovery_timeout_sec=3.0,
                )


class RosStateRuntime:
    def __init__(self) -> None:
        self.node: ApexStateNode | None = None
        self._thread: threading.Thread | None = None

    def start(self) -> ApexStateNode:
        if not rclpy.ok():
            rclpy.init()
        self.node = ApexStateNode()
        self._thread = threading.Thread(target=self._spin, daemon=True)
        self._thread.start()
        return self.node

    def stop(self) -> None:
        if rclpy.ok():
            rclpy.shutdown()
        if self._thread is not None:
            self._thread.join(timeout=1.0)
            self._thread = None
        if self.node is not None:
            self.node.destroy_node()
            self.node = None

    def _spin(self) -> None:
        if self.node is None:
            return
        try:
            rclpy.spin(self.node)
        except ExternalShutdownException:
            return


def _response_error_code(response: Any) -> int | None:
    value = getattr(response, "error_code", None)
    return _to_int(value)


def _to_int(value: Any) -> int | None:
    if value is None:
        return None
    try:
        return int(value)
    except (TypeError, ValueError):
        return None


def _int_response_success(response: Any) -> bool:
    if bool(getattr(response, "success", False)):
        return True
    error_code = _response_error_code(response)
    return error_code == 0


def _int_response_error(response: Any) -> dict[str, Any]:
    error_code = _response_error_code(response)
    message = str(getattr(response, "message", "") or "")
    error = f"Service returned error_code={error_code}"
    if message:
        error = f"{error}: {message}"
    return {"success": False, "error": error, "error_code": error_code, "message": message}
